import React, { useEffect, useRef, useState } from "react"

import ProjectDetail from "../../../components/ProjectDetail"
import Seo from "../../../components/Seo"
import * as shapeSnowStyles from "./css/shape-snow.module.css"

const GLYPHS = [
  ..."ABCDEFGHIJKLMNOPQRSTUVWXYZ".split(""),
  "\u3131",
  "\u3134",
  "\u3137",
  "\u3139",
  "\u3141",
  "\u3142",
  "\u3145",
  "\u3147",
  "\u3148",
  "\u314A",
  "\u314B",
  "\u314C",
  "\u314D",
  "\u314E",
  "\u314F",
  "\u3151",
  "\u3153",
  "\u3155",
  "\u3157",
  "\u315C",
  "\u3160",
  "\u3163",
]

const clamp = (value, min, max) => Math.max(min, Math.min(max, value))
const randomBetween = (min, max) => min + Math.random() * (max - min)
const randomGlyph = () => GLYPHS[Math.floor(Math.random() * GLYPHS.length)]

const sampleSnowLine = (width, height, x, time) => {
  const normalizedX = x / Math.max(width, 1)
  const ridge =
    Math.sin(normalizedX * 5.8 + time * 0.00008) * 10 +
    Math.sin(normalizedX * 11.6 + 1.4) * 6
  const centerLift =
    Math.max(0, 1 - Math.abs(normalizedX - 0.5) * 2) * height * 0.02

  return height * 0.83 - centerLift + ridge
}

const createStars = (count, width, height) =>
  Array.from({ length: count }, () => ({
    x: Math.random() * width,
    y: Math.random() * height * 0.7,
    size: randomBetween(0.4, 2.2),
    twinkleSpeed: randomBetween(0.0008, 0.004),
    twinklePhase: randomBetween(0, Math.PI * 2),
    baseOpacity: randomBetween(0.2, 0.7),
  }))

const createFlake = ({
  width,
  height,
  density,
  wind = 0,
  spawnAbove = false,
  lifted = false,
  originX,
  originY,
  glyph,
  depth,
  baseSize,
  opacity,
  direction = 0,
}) => {
  const flakeDepth = depth ?? randomBetween(0.3, 2.0)
  const densityBoost = 0.82 + density * 0.06

  let x = originX ?? Math.random() * width
  if (spawnAbove && originX === undefined) {
    if (wind > 0.5) {
      x = randomBetween(-width * 0.12, width * 0.78)
    } else if (wind < -0.5) {
      x = randomBetween(width * 0.22, width * 1.12)
    }
  }

  return {
    x,
    y:
      originY ??
      (lifted
        ? height * 0.82
        : spawnAbove
          ? -randomBetween(20, height * 0.4)
          : Math.random() * height),
    depth: flakeDepth,
    glyph: glyph ?? randomGlyph(),
    baseSize: baseSize ?? randomBetween(10, 26),
    fallVelocity: randomBetween(20, 75) * flakeDepth * densityBoost,
    sway: randomBetween(10, 30),
    sway2: randomBetween(4, 12),
    drift: randomBetween(0.15, 0.5),
    drift2: randomBetween(0.08, 0.25),
    phase: randomBetween(0, Math.PI * 2),
    phase2: randomBetween(0, Math.PI * 2),
    opacity: opacity ?? randomBetween(0.15, 0.65),
    rotation: randomBetween(-0.3, 0.3),
    spin: randomBetween(-0.2, 0.2),
    horizontalVelocity: lifted ? direction * randomBetween(26, 72) : 0,
    upwardVelocity: lifted ? randomBetween(24, 72) : 0,
    sparklePhase: randomBetween(0, Math.PI * 2),
    sparkleSpeed: randomBetween(0.002, 0.006),
    hueShift: randomBetween(-15, 15),
  }
}

const resetFlake = (flake, { width, height, density, wind }) => {
  const nextFlake = createFlake({
    width,
    height,
    density,
    wind,
    spawnAbove: true,
  })

  Object.assign(flake, nextFlake)
}

const createPileGlyph = ({ flake, width, height, time }) => {
  const anchorX = clamp(
    flake.x + randomBetween(-12, 12),
    18,
    Math.max(18, width - 18)
  )

  return {
    anchorX,
    baseY: sampleSnowLine(width, height, anchorX, time) - randomBetween(2, 16),
    depth: clamp(flake.depth + randomBetween(-0.08, 0.22), 0.9, 1.95),
    glyph: flake.glyph,
    baseSize: flake.baseSize * randomBetween(0.72, 0.96),
    opacity: clamp(flake.opacity + 0.18, 0.26, 0.76),
    rotation: randomBetween(-0.18, 0.18),
    phase: randomBetween(0, Math.PI * 2),
    driftResponse: randomBetween(4, 14),
    liftResponse: randomBetween(1.5, 4.5),
    bob: randomBetween(0.2, 0.7),
    hueShift: randomBetween(-10, 10),
  }
}

const liftPileGlyph = ({ glyph, width, height, density, wind }) =>
  createFlake({
    width,
    height,
    density,
    wind,
    lifted: true,
    originX: glyph.anchorX,
    originY: glyph.baseY - 2,
    glyph: glyph.glyph,
    depth: clamp(glyph.depth - 0.12, 0.72, 1.7),
    baseSize: glyph.baseSize * 0.92,
    opacity: clamp(glyph.opacity - 0.06, 0.16, 0.64),
    direction: wind >= 0 ? 1 : -1,
  })

const drawStars = (ctx, stars, time) => {
  stars.forEach(star => {
    const twinkle =
      0.5 + 0.5 * Math.sin(time * star.twinkleSpeed + star.twinklePhase)
    const alpha = star.baseOpacity * twinkle

    ctx.save()
    ctx.beginPath()
    ctx.arc(star.x, star.y, star.size, 0, Math.PI * 2)
    ctx.fillStyle = `rgba(220, 235, 255, ${alpha})`
    ctx.shadowBlur = star.size * 4 + twinkle * 6
    ctx.shadowColor = `rgba(180, 210, 255, ${alpha * 0.6})`
    ctx.fill()
    ctx.restore()
  })
}

const drawMoon = (ctx, width, height, time) => {
  const moonX = width * 0.82
  const moonY = height * 0.12
  const moonRadius = Math.min(width, height) * 0.04

  const pulse = 0.95 + 0.05 * Math.sin(time * 0.0005)

  ctx.save()
  const outerGlow = ctx.createRadialGradient(
    moonX, moonY, moonRadius * 0.5,
    moonX, moonY, moonRadius * 8
  )
  outerGlow.addColorStop(0, "rgba(180, 210, 255, 0.12)")
  outerGlow.addColorStop(0.3, "rgba(140, 180, 240, 0.06)")
  outerGlow.addColorStop(0.6, "rgba(100, 150, 220, 0.02)")
  outerGlow.addColorStop(1, "rgba(100, 150, 220, 0)")
  ctx.fillStyle = outerGlow
  ctx.fillRect(0, 0, width, height)

  ctx.beginPath()
  ctx.arc(moonX, moonY, moonRadius * 1.8 * pulse, 0, Math.PI * 2)
  const innerGlow = ctx.createRadialGradient(
    moonX, moonY, moonRadius * 0.3,
    moonX, moonY, moonRadius * 1.8
  )
  innerGlow.addColorStop(0, "rgba(210, 230, 255, 0.25)")
  innerGlow.addColorStop(0.5, "rgba(180, 210, 250, 0.08)")
  innerGlow.addColorStop(1, "rgba(180, 210, 250, 0)")
  ctx.fillStyle = innerGlow
  ctx.fill()

  ctx.beginPath()
  ctx.arc(moonX, moonY, moonRadius, 0, Math.PI * 2)
  const moonGrad = ctx.createRadialGradient(
    moonX - moonRadius * 0.3,
    moonY - moonRadius * 0.3,
    moonRadius * 0.1,
    moonX,
    moonY,
    moonRadius
  )
  moonGrad.addColorStop(0, "rgba(255, 255, 255, 0.95)")
  moonGrad.addColorStop(0.6, "rgba(220, 235, 255, 0.85)")
  moonGrad.addColorStop(1, "rgba(190, 215, 245, 0.75)")
  ctx.fillStyle = moonGrad
  ctx.shadowBlur = 30
  ctx.shadowColor = "rgba(200, 225, 255, 0.5)"
  ctx.fill()
  ctx.restore()
}

const drawAurora = (ctx, width, height, time) => {
  ctx.save()
  ctx.globalCompositeOperation = "screen"

  const bands = [
    { y: 0.18, hue: 160, sat: 60, amp: 0.04, freq: 0.0003, alpha: 0.04 },
    { y: 0.22, hue: 200, sat: 50, amp: 0.03, freq: 0.00025, alpha: 0.035 },
    { y: 0.15, hue: 280, sat: 40, amp: 0.035, freq: 0.00035, alpha: 0.025 },
  ]

  bands.forEach(band => {
    const wave = Math.sin(time * band.freq) * band.amp
    const centerY = height * (band.y + wave)

    const gradient = ctx.createLinearGradient(0, centerY - height * 0.15, 0, centerY + height * 0.15)
    gradient.addColorStop(0, `hsla(${band.hue}, ${band.sat}%, 60%, 0)`)
    gradient.addColorStop(0.3, `hsla(${band.hue}, ${band.sat}%, 55%, ${band.alpha * 0.6})`)
    gradient.addColorStop(0.5, `hsla(${band.hue}, ${band.sat}%, 50%, ${band.alpha})`)
    gradient.addColorStop(0.7, `hsla(${band.hue}, ${band.sat}%, 55%, ${band.alpha * 0.6})`)
    gradient.addColorStop(1, `hsla(${band.hue}, ${band.sat}%, 60%, 0)`)

    ctx.fillStyle = gradient

    ctx.beginPath()
    ctx.moveTo(0, centerY - height * 0.15)
    for (let x = 0; x <= width; x += 8) {
      const normalizedX = x / width
      const yOff =
        Math.sin(normalizedX * 6 + time * 0.0004) * height * 0.02 +
        Math.sin(normalizedX * 3 + time * 0.0002) * height * 0.015
      ctx.lineTo(x, centerY + yOff - height * 0.15)
    }
    ctx.lineTo(width, centerY + height * 0.15)
    for (let x = width; x >= 0; x -= 8) {
      const normalizedX = x / width
      const yOff =
        Math.sin(normalizedX * 6 + time * 0.0004) * height * 0.02 +
        Math.sin(normalizedX * 3 + time * 0.0002) * height * 0.015
      ctx.lineTo(x, centerY + yOff + height * 0.15)
    }
    ctx.closePath()
    ctx.fill()
  })

  ctx.restore()
}

const drawBackdrop = (ctx, width, height, wind, time) => {
  const skyGradient = ctx.createLinearGradient(0, 0, 0, height)
  skyGradient.addColorStop(0, "#010510")
  skyGradient.addColorStop(0.3, "#061020")
  skyGradient.addColorStop(0.6, "#0a1830")
  skyGradient.addColorStop(1, "#0b1628")

  ctx.fillStyle = skyGradient
  ctx.fillRect(0, 0, width, height)

  const hazeGradient = ctx.createRadialGradient(
    width * 0.5,
    height * 0.34,
    20,
    width * 0.5,
    height * 0.34,
    width * 0.56
  )
  hazeGradient.addColorStop(0, "rgba(178, 221, 255, 0.14)")
  hazeGradient.addColorStop(0.42, "rgba(103, 164, 229, 0.06)")
  hazeGradient.addColorStop(1, "rgba(103, 164, 229, 0)")

  ctx.fillStyle = hazeGradient
  ctx.fillRect(0, 0, width, height)

  const floorGradient = ctx.createLinearGradient(0, height * 0.58, 0, height)
  floorGradient.addColorStop(0, "rgba(18, 34, 58, 0)")
  floorGradient.addColorStop(0.35, "rgba(18, 34, 58, 0.42)")
  floorGradient.addColorStop(1, "rgba(5, 10, 20, 0.88)")

  ctx.fillStyle = floorGradient
  ctx.fillRect(0, height * 0.54, width, height * 0.46)

  ctx.save()
  ctx.beginPath()
  ctx.ellipse(
    width / 2 + wind * width * 0.018,
    height * 0.86,
    width * 0.34,
    height * 0.055,
    0,
    0,
    Math.PI * 2
  )
  ctx.fillStyle = "rgba(212, 236, 255, 0.06)"
  ctx.fill()
  ctx.restore()
}

const drawSnowGround = (ctx, width, height, time, wind) => {
  ctx.save()
  ctx.beginPath()
  ctx.moveTo(0, sampleSnowLine(width, height, 0, time))
  for (let x = 0; x <= width; x += 8) {
    ctx.lineTo(x, sampleSnowLine(width, height, x, time))
  }
  ctx.lineTo(width, height)
  ctx.lineTo(0, height)
  ctx.closePath()

  const groundGrad = ctx.createLinearGradient(
    0,
    height * 0.8,
    0,
    height
  )
  groundGrad.addColorStop(0, "rgba(210, 235, 255, 0.12)")
  groundGrad.addColorStop(0.3, "rgba(190, 220, 250, 0.08)")
  groundGrad.addColorStop(1, "rgba(160, 200, 240, 0.04)")
  ctx.fillStyle = groundGrad
  ctx.fill()

  ctx.beginPath()
  ctx.moveTo(0, sampleSnowLine(width, height, 0, time))
  for (let x = 0; x <= width; x += 8) {
    ctx.lineTo(x, sampleSnowLine(width, height, x, time))
  }
  ctx.strokeStyle = `rgba(220, 240, 255, ${0.15 + Math.abs(wind) * 0.03})`
  ctx.lineWidth = 1.5
  ctx.shadowBlur = 12
  ctx.shadowColor = "rgba(180, 220, 255, 0.2)"
  ctx.stroke()
  ctx.restore()
}

const drawFlake = (ctx, flake, height, wind, time) => {
  const perspective =
    0.6 + flake.depth * 0.45 + (flake.y / Math.max(height, 1)) * 0.15
  const size = flake.baseSize * perspective

  const sparkle =
    0.5 + 0.5 * Math.sin(time * flake.sparkleSpeed + flake.sparklePhase)
  const alpha = clamp(
    flake.opacity *
      (0.45 + flake.depth * 0.2 + (flake.y / height) * 0.1) *
      (0.85 + sparkle * 0.15),
    0.06,
    0.88
  )

  const x =
    flake.x +
    Math.sin(time * 0.001 * flake.drift + flake.phase) * flake.sway +
    Math.sin(time * 0.001 * flake.drift2 + flake.phase2) * flake.sway2 +
    wind * (8 + flake.depth * 12)

  const hue = 210 + flake.hueShift
  const sat = 30 + flake.depth * 15
  const lightness = 90 + sparkle * 8

  ctx.save()
  ctx.translate(x, flake.y)
  ctx.rotate(flake.rotation)
  ctx.font = `${size}px "Avenir Next", "Pretendard Variable", "Noto Sans KR", sans-serif`
  ctx.textAlign = "center"
  ctx.textBaseline = "middle"

  if (flake.depth > 0.8) {
    ctx.shadowBlur = 10 + flake.depth * 8 + sparkle * 6
    ctx.shadowColor = `hsla(${hue}, ${sat}%, 80%, ${0.3 + sparkle * 0.15})`
  }

  if (flake.depth > 1.5 && sparkle > 0.85) {
    ctx.shadowBlur = 20 + sparkle * 12
    ctx.shadowColor = `hsla(${hue}, ${sat + 10}%, 85%, ${0.5 + sparkle * 0.2})`
  }

  ctx.fillStyle = `hsla(${hue}, ${sat}%, ${lightness}%, ${alpha})`
  ctx.fillText(flake.glyph, 0, 0)
  ctx.restore()
}

const drawPileGlyph = (ctx, glyph, time, wind) => {
  const driftX =
    wind * glyph.driftResponse * glyph.depth +
    Math.sin(time * 0.0014 + glyph.phase) * glyph.bob
  const liftY =
    Math.abs(wind) * glyph.liftResponse +
    Math.sin(time * 0.001 + glyph.phase) * 0.8
  const size = glyph.baseSize * (0.82 + glyph.depth * 0.22)
  const alpha = clamp(glyph.opacity - Math.abs(wind) * 0.04, 0.16, 0.82)
  const hue = 210 + glyph.hueShift

  ctx.save()
  ctx.translate(glyph.anchorX + driftX, glyph.baseY - liftY)
  ctx.rotate(glyph.rotation + wind * 0.03)
  ctx.font = `${size}px "Avenir Next", "Pretendard Variable", "Noto Sans KR", sans-serif`
  ctx.textAlign = "center"
  ctx.textBaseline = "middle"
  ctx.shadowBlur = 8 + glyph.depth * 4
  ctx.shadowColor = `hsla(${hue}, 40%, 78%, 0.22)`
  ctx.fillStyle = `hsla(${hue}, 25%, 96%, ${alpha})`
  ctx.fillText(glyph.glyph, 0, 0)
  ctx.restore()
}

const ShapeSnowCanvas = ({ speed, density }) => {
  const canvasRef = useRef(null)
  const optionsRef = useRef({ speed, density })

  useEffect(() => {
    optionsRef.current = { speed, density }
  }, [density, speed])

  useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas) {
      return undefined
    }

    const ctx = canvas.getContext("2d")
    if (!ctx) {
      return undefined
    }

    let animationFrameId
    let width = window.innerWidth
    let height = window.innerHeight
    let lastFrameTime = 0
    let wind = 0
    let targetWind = 0
    let lastPointerX = null
    let lastPointerTime = 0
    let flakes = []
    let pileGlyphs = []
    let stars = createStars(120, width, height)

    const syncFlakePopulation = forceSync => {
      const currentOptions = optionsRef.current
      const targetCount = 50 + currentOptions.density * 32

      if (flakes.length < targetCount) {
        const additionCount = forceSync
          ? targetCount - flakes.length
          : Math.min(5, targetCount - flakes.length)

        flakes = flakes.concat(
          Array.from({ length: additionCount }, () =>
            createFlake({
              width,
              height,
              density: currentOptions.density,
              wind,
              spawnAbove: !forceSync,
            })
          )
        )
        return
      }

      if (flakes.length > targetCount) {
        const removalCount = forceSync
          ? flakes.length - targetCount
          : Math.min(5, flakes.length - targetCount)

        flakes.splice(flakes.length - removalCount, removalCount)
      }
    }

    const resize = () => {
      width = window.innerWidth
      height = window.innerHeight

      const devicePixelRatio = window.devicePixelRatio || 1
      canvas.width = width * devicePixelRatio
      canvas.height = height * devicePixelRatio
      canvas.style.width = `${width}px`
      canvas.style.height = `${height}px`
      ctx.setTransform(devicePixelRatio, 0, 0, devicePixelRatio, 0, 0)

      flakes = []
      pileGlyphs = []
      stars = createStars(120, width, height)
      syncFlakePopulation(true)
    }

    const handlePointerMove = event => {
      const now = window.performance.now()

      if (lastPointerX !== null) {
        const deltaX = event.clientX - lastPointerX
        const deltaTime = Math.max(16, now - lastPointerTime)
        const velocity = clamp(deltaX / deltaTime / 1.7, -1.35, 1.35)

        targetWind = clamp(targetWind + velocity * 0.42, -1.75, 1.75)
      }

      lastPointerX = event.clientX
      lastPointerTime = now
    }

    const handlePointerLeave = () => {
      lastPointerX = null
      lastPointerTime = 0
      targetWind *= 0.45
    }

    const maybeLiftPileGlyph = (currentOptions, delta) => {
      if (pileGlyphs.length < 8 || Math.abs(wind) < 0.86) {
        return
      }

      const chance = clamp((Math.abs(wind) - 0.82) * delta * 3.4, 0, 0.035)
      if (Math.random() >= chance) {
        return
      }

      const index = Math.floor(Math.random() * pileGlyphs.length)
      const [glyph] = pileGlyphs.splice(index, 1)
      if (!glyph) {
        return
      }

      flakes.push(
        liftPileGlyph({
          glyph,
          width,
          height,
          density: currentOptions.density,
          wind,
        })
      )
    }

    const draw = now => {
      const currentOptions = optionsRef.current
      const delta = Math.min((now - lastFrameTime) / 1000 || 0.016, 0.05)
      lastFrameTime = now

      targetWind *= Math.pow(0.992, delta * 60)
      wind += (targetWind - wind) * Math.min(1, delta * 4.8)

      syncFlakePopulation(false)

      const pileLimit = 26 + currentOptions.density * 18
      if (pileGlyphs.length > pileLimit) {
        pileGlyphs.splice(0, pileGlyphs.length - pileLimit)
      }

      maybeLiftPileGlyph(currentOptions, delta)

      drawBackdrop(ctx, width, height, wind, now)
      drawStars(ctx, stars, now)
      drawAurora(ctx, width, height, now)
      drawMoon(ctx, width, height, now)

      flakes.forEach(flake => {
        flake.upwardVelocity = Math.max(0, flake.upwardVelocity - 84 * delta)
        flake.y +=
          flake.fallVelocity *
            currentOptions.speed *
            (0.55 + flake.depth * 0.5) *
            delta -
          flake.upwardVelocity * delta
        flake.horizontalVelocity += wind * 9 * delta
        flake.horizontalVelocity *= Math.pow(0.988, delta * 60)
        flake.x += flake.horizontalVelocity * delta
        flake.rotation += flake.spin * delta

        const floorY = sampleSnowLine(width, height, flake.x, now)

        if (flake.y >= floorY) {
          if (
            pileGlyphs.length < pileLimit &&
            Math.random() < 0.34 + flake.depth * 0.12
          ) {
            pileGlyphs.push(
              createPileGlyph({
                flake,
                width,
                height,
                time: now,
              })
            )
          }

          resetFlake(flake, {
            width,
            height,
            density: currentOptions.density,
            wind,
          })
          return
        }

        if (
          flake.y > height + 48 ||
          flake.x < -140 ||
          flake.x > width + 140
        ) {
          resetFlake(flake, {
            width,
            height,
            density: currentOptions.density,
            wind,
          })
        }
      })

      drawSnowGround(ctx, width, height, now, wind)

      flakes
        .slice()
        .sort((left, right) => left.depth - right.depth)
        .forEach(flake => drawFlake(ctx, flake, height, wind, now))

      pileGlyphs
        .slice()
        .sort((left, right) => left.depth - right.depth)
        .forEach(glyph => drawPileGlyph(ctx, glyph, now, wind))

      animationFrameId = window.requestAnimationFrame(draw)
    }

    resize()
    animationFrameId = window.requestAnimationFrame(draw)
    window.addEventListener("resize", resize)
    window.addEventListener("pointermove", handlePointerMove)
    window.addEventListener("pointerleave", handlePointerLeave)
    window.addEventListener("blur", handlePointerLeave)

    return () => {
      window.removeEventListener("resize", resize)
      window.removeEventListener("pointermove", handlePointerMove)
      window.removeEventListener("pointerleave", handlePointerLeave)
      window.removeEventListener("blur", handlePointerLeave)
      window.cancelAnimationFrame(animationFrameId)
    }
  }, [])

  return <canvas ref={canvasRef} className={shapeSnowStyles.canvas} />
}

const ShapeSnowMotion = () => {
  const [speed, setSpeed] = useState(1)
  const [density, setDensity] = useState(3)

  return (
    <ProjectDetail mainClassName={shapeSnowStyles.page}>
      <div className={shapeSnowStyles.scene}>
        <ShapeSnowCanvas speed={speed} density={density} />

        <div className={shapeSnowStyles.controls}>
          <label className={shapeSnowStyles.control}>
            <span className={shapeSnowStyles.controlLabel}>Speed</span>
            <span className={shapeSnowStyles.controlValue}>
              {speed.toFixed(1)}
            </span>
            <input
              type="range"
              min="0.6"
              max="2.4"
              step="0.1"
              value={speed}
              onChange={event =>
                setSpeed(Number.parseFloat(event.target.value))
              }
              className={shapeSnowStyles.slider}
            />
          </label>

          <label className={shapeSnowStyles.control}>
            <span className={shapeSnowStyles.controlLabel}>Amount</span>
            <span className={shapeSnowStyles.controlValue}>{density}</span>
            <input
              type="range"
              min="1"
              max="5"
              step="1"
              value={density}
              onChange={event =>
                setDensity(Number.parseInt(event.target.value, 10))
              }
              className={shapeSnowStyles.slider}
            />
          </label>

          <p className={shapeSnowStyles.hint}>Move mouse left and right</p>
        </div>
      </div>
    </ProjectDetail>
  )
}

export const Head = () => (
  <Seo
    title="Shape Snow Motion"
    description="Interactive letter snow sways in the wind, gathers on the ground, and lifts back into a layered blizzard."
    keywords={["Motion", "Shape Snow", "Canvas", "Interactive Snow"]}
  />
)

export default ShapeSnowMotion
